import "../../styles/index-base.css";
import "../../styles/components/badge.css";
import { X } from "@phosphor-icons/react";
import type { ComponentPropsWithRef, ReactNode } from "react";
import { cn } from "../../lib/cn";

export type BadgeProps = ComponentPropsWithRef<"span"> & {
  variant?: "neutral" | "strong" | "outline" | "success" | "warning" | "danger";
  leadingIcon?: ReactNode;
  removable?: boolean;
  onRemove?: () => void;
  removeLabel?: string;
};

export function Badge({
  className,
  variant = "neutral",
  leadingIcon,
  removable,
  onRemove,
  removeLabel = "Remove",
  children,
  ...props
}: BadgeProps) {
  return (
    <span className={cn("ix-badge", `ix-badge--${variant}`, className)} {...props}>
      {leadingIcon && <span className="ix-badge__icon" aria-hidden="true">{leadingIcon}</span>}
      <span className="ix-badge__label">{children}</span>
      {removable && (
        <button type="button" className="ix-badge__remove" aria-label={removeLabel} onClick={onRemove}>
          <X aria-hidden="true" />
        </button>
      )}
    </span>
  );
}

/* Generated from src/styles.css. Do not edit directly. */

@layer index.tokens, index.base, index.components;

@layer index.components {
.ix-badge {
  display: inline-flex;
  min-width: 0;
  height: 22px;
  align-items: center;
  gap: 5px;
  padding: 0 7px;
  border: 1px solid transparent;
  border-radius: 999px;
  background: var(--ix-gray-100);
  color: var(--ix-ink-secondary);
  font-size: 11.5px;
  font-weight: 520;
  line-height: 1;
  white-space: nowrap;
}

.ix-badge__icon,
.ix-badge__icon svg { width: 12px; height: 12px; flex: 0 0 auto; }

.ix-badge__label { overflow: hidden; text-overflow: ellipsis; }

.ix-badge__remove {
  display: grid;
  width: 18px;
  height: 18px;
  margin-right: -5px;
  place-items: center;
  border: 0;
  border-radius: 999px;
  background: transparent;
  color: currentColor;
  cursor: pointer;
}

.ix-badge__remove svg { width: 11px; height: 11px; }

.ix-badge__remove:focus-visible { outline: 1.5px solid currentColor; outline-offset: -2px; }

@media (hover: hover) and (pointer: fine) {
.ix-badge__remove:hover { background: var(--ix-hover); color: var(--ix-ink); }
}

.ix-badge__remove { transition: color var(--ix-hover-duration), background-color var(--ix-hover-duration), transform var(--ix-press-duration) var(--ix-ease-out); }

.ix-badge__remove:active { transform: scale(.96); }

@media (prefers-reduced-motion: reduce) {
.ix-badge__remove:active { transform: none; }
}
}
